"""Report the authenticated v3 postmortem without changing a research policy."""
from collections import Counter
from datetime import datetime, timezone
from html import escape
from html.parser import HTMLParser
from pathlib import Path
import hashlib
import json

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np

REPO=Path(__file__).resolve().parents[1]
OUT=REPO/'data/backtests/analysis/olr_precision_diagnosis_20261011'
PRIOR=REPO/'data/backtests/analysis/olr_precision_20261011'

def sha(p):
    with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()

def read(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def num(x,n=3):return f'{x:,.{n}f}'
def money(x):return f'KRW {x/1e6:+.3f}m'
def table(headers,rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def main():
    d=read(OUT/'diagnosis.json');r=read(PRIOR/'results.json');profile=read(PRIOR/'selected_research_policy.json')
    assert profile['results_sha256']==sha(PRIOR/'results.json')
    assert d['script_sha256']==sha(REPO/'scripts/olr_precision_diagnosis_v4.py')
    assert all(sha(p)==v for p,v in d['source_sha256'].items())
    c={x['label']:x for x in r['candidates']};control=c['selected_control'];struct=c['structural_partial_half']
    matches=struct['trade_comparison']['oos']['all_matches']
    largest=max(matches,key=lambda x:x['pnl_delta']);total=struct['trade_comparison']['oos']['pnl_delta']
    worsening=[x for x in matches if x['symbol'] in ('011790','069960') and x['pnl_delta']<0]
    months={w:{month:row['return_pct']-control['windows'][w]['months'][month]['return_pct'] for month,row in struct['windows'][w]['months'].items()} for w in ('train','oos')}
    snapshots=read(Path.home()/'.codex/research/olr_precision_v3/oos/inputs/files/research/olr_continuous_history/olr_snapshots.json')
    flow=[]
    for row in snapshots:
        sole=[s for s,v in row['metadata'].get('afternoon_rejected_symbols',{}).items() if v==['lagged_sector_flow_below_floor']]
        if sole:flow.append({'date':row['trade_date'],'symbols':sole,'final_candidates':len(row['candidates'])})
    findings={'structural_exit':{'pnl_delta':total,'largest_improvement':largest,'largest_share_pct':100*largest['pnl_delta']/total,
        'other_matched_trades_net_delta':total-largest['pnl_delta'],'two_worsened_losers':worsening,
        'two_worsened_losers_delta':sum(x['pnl_delta'] for x in worsening),'monthly_return_delta_pp':months},
        'flow_rescue_upper_bound':{'names':sum(len(x['symbols']) for x in flow),'days':len(flow),
            'empty_days':sum(x['final_candidates']==0 for x in flow),'rows':flow},
        'interpretation':'Descriptive accounting and stage-local upper bounds, not independent causal estimates or new strategy performance.'}
    (OUT/'additional_findings.json').write_text(json.dumps(findings,indent=2)+'\n',encoding='utf-8')

    names=['Liquidation tail','Selective half exit','Confirmation 7–9','Half exit + 7–9']
    labels=['liquidation_tail_es90','structural_partial_half','late_confirmation_9','risk_plus_late_confirmation']
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
    fig,axs=plt.subplots(2,2,figsize=(15,10),layout='constrained')
    y=np.arange(4);height=.34
    for offset,w,color,title in [(-height/2,'train','#2667a5','IS'),(height/2,'oos','#dc7a27','OOS')]:
        vals=[c[k]['windows'][w]['return_pct']-control['windows'][w]['return_pct'] for k in labels]
        b=axs[0,0].barh(y+offset,vals,height,label=title,color=color)
        axs[0,0].bar_label(b,fmt='%+.2f',padding=3,fontsize=9)
    axs[0,0].set(yticks=y,yticklabels=names,xlabel='Return change versus retained control (percentage points)',title='A. More activity was costly; the selective exit helped returns',xlim=(-14,4));axs[0,0].invert_yaxis();axs[0,0].axvline(0,color='#777',lw=.8);axs[0,0].legend(loc='lower left')
    vals=[control['windows']['oos']['drawdown_pct']-c[k]['windows']['oos']['drawdown_pct'] for k in labels]
    b=axs[0,1].barh(y,vals,color=['#8395ab','#2e8b70','#8395ab','#8395ab'])
    axs[0,1].bar_label(b,fmt='%.3f',padding=4)
    axs[0,1].axvline(.75,color='#ac3737',ls='--',label='Required reduction: 0.75 pp')
    axs[0,1].set(yticks=y,yticklabels=names,xlim=(0,.96),xlabel='OOS intraday DD reduction (percentage points)',title='B. None reduced the peak-to-trough loss enough');axs[0,1].invert_yaxis();axs[0,1].legend(loc='lower right')
    examples=d['estimator_examples'];y2=np.arange(len(examples))
    for offset,key,color,title in [(-height/2,'proposed_quote','#6f4e8a','Quoted at proposed size'),(height/2,'requote_at_approved_size','#44a395','Requoted at approved size')]:
        b=axs[1,0].barh(y2+offset,[100*x[key]['fraction'] for x in examples],height,color=color,label=title)
        axs[1,0].bar_label(b,fmt='%.2f',padding=3,fontsize=8)
    axs[1,0].set(yticks=y2,yticklabels=[x['symbol']+' '+x['entry'] for x in examples],xlabel='Estimated tail loss (% of requested notional)',xlim=(0,32),title='C. A large-size quote remained fixed after risk clipping');axs[1,0].invert_yaxis();axs[1,0].legend(fontsize=9,loc='lower right')
    v=[largest['pnl_delta']/1e6,(total-largest['pnl_delta'])/1e6,total/1e6]
    b=axs[1,1].barh([0,1,2],v,color=['#2e8b70','#b14a4a','#2667a5']);axs[1,1].bar_label(b,fmt='%+.3f',padding=5)
    axs[1,1].set(yticks=[0,1,2],yticklabels=['034730, May 11 entry','All other matched trades','Aggregate OOS change'],xlabel='Selective half-exit P&L change (million KRW)',xlim=(-.4,1.8),title='D. One event accounts for more than the OOS benefit');axs[1,1].invert_yaxis();axs[1,1].axvline(0,color='#777',lw=.8)
    fig.suptitle('OLR precision v3: why no successor qualified',fontsize=20,fontweight='bold')
    fig.supxlabel('Historical research diagnosis. Panel C changes only an estimator input; it is not a new portfolio result.',fontsize=10)
    fig.savefig(OUT/'diagnosis.png',dpi=170);plt.close(fig)

    blocks=[]
    def h(t):blocks.append('<h2>'+escape(t)+'</h2>')
    def p(t):blocks.append('<p>'+t+'</p>')
    blocks.append('<h1>OLR: why the precision round failed, and what to test next</h1>')
    p('<strong>The failure is diagnostic, not evidence that improvement is impossible.</strong> The round combined an overconservative, size-inconsistent tail estimator, a useful but concentrated gradual-loss exit, and a frequency extension with negative incremental economics. None adequately addressed the dominant fast losses and correlated exposure. The right next step is to repair those mechanisms and measure their individual value before combining them—not to loosen the final acceptance gates.')
    p('This report adds an authenticated, read-only reconstruction of six liquidation estimates, the cash and risk budgets behind missing valid signals, and the concentration of the selective-exit benefit. It changes no frozen inputs, strategy policy, selected profile or earlier results. New estimator values and arithmetic drawdown distances below are diagnostics, not simulated strategy returns.')
    blocks.append('<figure><img src="diagnosis.png" alt="Four panels compare return changes, drawdown improvement, size-sensitive tail estimates and concentration of the exit benefit."><figcaption>All performance panels use completed native v3 cases. Tail requotes do not imply feasible larger allocations.</figcaption></figure>')
    h('1. The outcome, measured against the actual objective')
    rows=[]
    for title,windows in [('Original',r['references']['original']),('Guard',r['references']['guard']['windows'])]+[(name,c[label]['windows']) for name,label in [('Retained control','selected_control'),('Liquidation tail','liquidation_tail_es90'),('Selective half exit','structural_partial_half'),('Confirmation through bar 9','late_confirmation_9'),('Half exit + later confirmation','risk_plus_late_confirmation')]]:
        rows.append([title]+[num(windows[w][k]) if k not in ('trades','entry_days') else str(windows[w][k]) for w in ('train','oos') for k in ('return_pct','drawdown_pct','trades','entry_days')])
    blocks.append(table(['Policy','IS return %','IS DD %','IS entries','IS entry days','OOS return %','OOS DD %','OOS entries','OOS entry days'],rows))
    p('IS is August 7, 2025–March 31, 2026; OOS is April 1–July 10, 2026. Returns are cumulative, not annualized. Maximum drawdown uses intraday marked equity. The unequal period lengths mean raw IS and OOS total returns should not be compared as equal-horizon expected returns. April–July has now been repeatedly inspected and used for design; it is a development period, not independent validation.')
    p('The strongest IS return floor is <strong>52.138595%</strong>, with the original-minus-3-point and guard-minus-3-point floors also retained. IS DD must stay at or below 10.174960%. OOS return must reach 12.439796% and DD fall to 15.530715% or less; genuine entries must reach 186 IS and 47 OOS, with at least 88 and 29 entry days. The selective exit passes every nominal requirement except OOS DD and OOS entry count. The tail rule substantially misses IS preservation; the late-entry rule supplies the extra OOS trade but loses return in both periods. Their combination inherits the late-entry weakness.')
    h('2. The tail estimator transferred the wrong kind of risk between stocks')
    p('<strong>Confirmed implementation behavior:</strong> the rule applies the same proposed KRW notional to every historical peer. Historical shares are limited by that peer’s recorded execution capacity. Unliquidated shares are valued at zero. The result combines a price-loss estimate with a severe liquidity-impairment assumption, then transfers that combined estimate to the candidate stock. This is inappropriate when the candidate is liquid and the peer is much less liquid. Conservatism alone is not the problem; the conservatism is assigned to the wrong exposure.')
    e=next(x for x in examples if x['symbol']=='034020')
    p(f'For <strong>034020 on April 23</strong>, the proposed quote was KRW {e["proposed_quote"]["notional_upper"]/1e6:.3f}m. The stock’s own tail estimate was {100*e["proposed_quote"]["symbol_tail_mean"]:.3f}%, with all 60 own-stock scenarios fully liquidated. Its only same-sector peer inside the declared universe, 298050, had incomplete liquidation in 50 of 60 scenarios and an 88.585% tail estimate. The 75% own / 25% peer blend became <strong>{100*e["proposed_quote"]["fraction"]:.3f}%</strong>. Control quantity was 553 shares; the tail case filled 125. The matched winner lost KRW 2.102m of profit, primarily through sizing.')
    p('This was not an isolated example. The peer blend alone pushed the estimate above the ATR floor in <strong>47 of 183 admitted IS trades</strong>, with a loss budget binding in 30; the corresponding OOS counts were 7 of 46 and 3. These are admitted-trade counts, not a census of all rejected intents. Sixty daily observations from a single peer do not provide sixty independent counterparties. The peer-count requirement and shrinkage strength must account for distinct names, date clustering, coverage and liquidity comparability.')
    p('<strong>A second confirmed issue is inconsistent sizing.</strong> The loss estimate is quoted once at the upper proposed notional, including possible recycling, then kept fixed after risk clipping. Because the estimator itself increases with size, a reduced allocation can remain priced as though it were the much larger original order.')
    blocks.append(table(['Symbol / entry','Own tail %','Peer tail %','Blend at proposed size %','Blend at approved size %','ATR floor %'],[[x['symbol']+' / '+x['entry'],num(x['proposed_quote']['symbol_tail_mean']*100),num(x['proposed_quote']['peer_tail_mean']*100),num(x['proposed_quote']['fraction']*100),num(x['requote_at_approved_size']['fraction']*100),num(x['atr_fraction']*100)] for x in examples]))
    p('The largest fast-loss example, 042660, illustrates the other side of the selectivity problem: its 5.143% blended tail estimate stayed below the existing 7.067% ATR floor. The new tail estimate therefore did not directly tighten that trade’s per-share loss allowance, while the peer-liquidity penalty was sharply reducing major winners elsewhere. A quantity change caused indirectly by earlier capital differences is not evidence that the intended risk mechanism identified this trade.')
    p('All six original estimates were reproduced exactly from the frozen panel. For 000720, the blend falls from 19.834% to 5.309% when evaluated at the actual approved notional. This demonstrates an overstatement at the approved size; it does not establish that the original large order would satisfy risk limits. Growing the order increases the risk estimate again.')
    p('<strong>Targeted repair:</strong> separate transferable peer price shocks from the candidate’s own liquidation capacity. Preserve conservative treatment of unsupported own-stock liquidity and explicit data-quality flags. Apply peer price scenarios through the candidate’s own executable volume/participation curve; do not inherit a peer’s inability to liquidate the same cash amount. Solve for the largest feasible integer quantity using its own quantity-dependent loss, cash and position/sector/account constraints, including pending orders and recycled extras. Requote the total intended position, not only an incremental top-up. Keep the ATR floor and existing loss budgets during the architectural comparison.')
    p('Use staged ablations: first correct quantity self-consistency while retaining the old scenario definition; then separate peer price and own liquidity. This distinguishes an allocation defect from a changed economic risk model. Precheck monotonicity, lack of future data, sparse-peer fallbacks, exact budget satisfaction and no change when the overlay is disabled before native performance tests. A repair can restore both winners and losers: 403870 also benefited from the old excessive peer penalty, so removing it without a better risk model can increase its loss.')
    h('3. The selective exit improved returns, but not the dominant drawdown mechanism')
    p(f'The structural half exit raised IS return by {struct["windows"]["train"]["return_pct"]-control["windows"]["train"]["return_pct"]:.3f} points and OOS return by {struct["windows"]["oos"]["return_pct"]-control["windows"]["oos"]["return_pct"]:.3f} points. It left every matched OOS winner’s exit time and price unchanged. That is useful evidence of selectivity, but it does not establish reliable continuation-value discrimination.')
    p(f'<strong>The OOS benefit is concentrated:</strong> the 034730 May 11 entry improved by {money(largest["pnl_delta"])}, or {findings["structural_exit"]["largest_share_pct"]:.1f}% of the aggregate {money(total)} improvement. All other matched trades contributed {money(total-largest["pnl_delta"])} in aggregate. The 011790 and 069960 losing trades together worsened by {money(findings["structural_exit"]["two_worsened_losers_delta"])} because an earlier sale forfeited subsequent partial recovery. This subtraction is accounting, not a strategy replay with one event removed; changing an event can alter later capital and fills.')
    blocks.append(table(['OOS month','Selective-exit return increment, pp'],[[month,f'{value:+.6f}'] for month,value in months['oos'].items()]))
    p('The exit rule requires at least three completed bars and repeated structural weakness. It cannot remove losses that have already occurred before the first executable 09:05 open. The old tail panel already included that first capacity-eligible price; there was no omitted-first-bar repair to make. In the selective-exit case the fast 042660 and 403870 exits stayed at the same prices and times, while quantities rose from 490 to 495 and 475 to 481 as capital changed. Those two losses worsened by approximately KRW 0.103m in total.')
    p('The control peak was KRW 131.797m on May 15 at 09:00 and the trough KRW 110.340m on July 9 at 12:15. The selective exit moved these to KRW 132.858m and KRW 111.592m. Much of its saving happened before the peak and raised both endpoints; the absolute peak-to-trough decline fell by only about KRW 0.192m. Higher total return therefore translated into just a 0.274-point DD improvement.')
    p('Control daily-close DD was 10.940%, compared with 16.281% intraday. This shows the importance of opening marks and profit retreat; it does not justify replacing the intraday risk metric with the smaller close-only number. The May 15 marked peak is not assumed to be an executable full-position sale.')
    gap=d['drawdown_gate_gap']
    p(f'At the selective-exit peak held fixed, another <strong>KRW {gap["additional_trough_wealth_needed_if_peak_unchanged"]:,.0f}</strong> at the trough would close the remaining registered DD gap. This gives the scale of the shortfall; it is not a target to fit using dates or known losing symbols. Any real policy change can move both peak and trough.')
    p('<strong>Next exit work:</strong> preserve the exact structural exit as a research component and test combined execution stress and no-upward-compounding directly. Examine all triggered states for the value of selling now versus retaining the remaining exposure under real execution delays and capacity. Report decision-weighted and notional-weighted continuation losses, recovered losers, removed winners and profit retreat. Evaluate concentration by event and month. Do not tune the −0.4R threshold or add symbol exclusions to rescue the April–July outcome. An eventual loser label is not the correct decision target; the relevant quantity is the additional executable proceeds expected from waiting, net of incremental costs and risk.')
    h('4. Exposure before a fast shock is the missing risk control')
    p('The major drawdown reflects both losing trades and retreat from unrealized gains. In the prior authenticated attribution, four losers explained 66.79% of the peak-to-trough decline and three eventual winners another 27.29%. The 042660 and 403870 losses alone explained about 42.5%. A broad tightening of exits can damage winners without creating liquidity before the first eligible execution.')
    p('The retained allocator can put about 65% of capital in one name. Actual gross exposure remained cash-funded, with an observed maximum around 99.424%; leverage was not required to produce this drawdown. Same-sector ship exposure reached roughly 75.28% of NAV. Existing 4% / 6% / 8% loss allowances are entry-ATR scenarios plus modeled costs. They are not hard realized-loss bounds. Held and pending quantities continue to consume entry-metadata risk; summing these independent allowances does not revalue a common gap from current marks or protect accumulated profits.')
    p('<strong>Highest-value structural hypothesis:</strong> assess the incremental liquidation loss of the whole proposed portfolio under aligned historical dates, measured from current causal marks and actual quantities. Preserve common sector/market shocks across names. Account for each name’s own liquidation curve, costs and pending orders, and compare proposed risk with already-held exposure. Use this to limit the marginal concentration that creates a budget breach, rather than imposing another blanket name cap. Test admission/reallocation first; an additional pre-close reassessment is a separate registered mechanism and must allow only executable trims, with no assumed release of capital before fills.')
    p('This hypothesis directly targets fast gaps and exposure built on unrealized profits while leaving a large position possible when its supported liquidation risk is acceptable. It is not proven by the present data. A 60-session tail can miss a new stress regime; aligned scenarios, coverage, maximum-versus-average tail loss and realized overshoots must be disclosed. Do not calibrate a new portfolio threshold to the two known worst trades or assume summing marginal expected-shortfall values estimates portfolio expected shortfall.')
    h('5. Frequency failed because later confirmations were weak and resources were scarce')
    p('Extending confirmation from six to nine bars admitted ten genuine late IS entries with approximately KRW 108.834m of aggregate entry notional and <strong>KRW −2.330m</strong> net P&L. Four won and six lost. The full policy lost 5.936 IS return points through those entries, displaced opportunities and changed sizing. It removed the 034220 February 24 winner, worth approximately KRW 1.126m in the control. OOS added one 112610 entry at 15:10, with KRW 5.377m actual notional and KRW −26,046 net P&L. The mechanism bought more trades without demonstrating more alpha.')
    p(f'Adding that same frequency leg to the selective exit reduced IS return by {abs(d["late_extension_increment_on_structural"]["train"]["adding_late_to_structural_return_delta_pp"]):.3f} points and OOS return by {abs(d["late_extension_increment_on_structural"]["oos"]["adding_late_to_structural_return_delta_pp"]):.4f} points. The combination’s failure is therefore largely explained by a weak frequency component, not the absence of an interaction search.')
    p('The OOS funnel contains 67 eligible entry snapshots, 32 empty: 16 already empty at the daily stage and 16 emptied by afternoon selection. All 74 final candidates were within the first six ranks. Forty-six entered, 21 lacked a six-bar confirmation and seven confirmed but did not enter. Three of those seven were already held. Raising slots or retrying every rejection cannot create meaningful new opportunities from this set.')
    funding=[x for x in d['existing_valid_signal_funding'] if x['window']=='oos']
    blocks.append(table(['Signal','Unreserved cash KRW','Remaining binding risk KRW','One-share ATR risk before costs KRW','Observed constraint'],[[x['symbol']+' / '+x['date'],num(x['unreserved_cash'],0),num(x['minimum_risk_headroom'],0),num(x['minimum_unit_risk_before_costs'],0),'Portfolio risk exhausted' if x['symbol']=='009150' else 'Sector risk exhausted' if x['symbol']=='000810' else 'Cash below one share'] for x in funding]))
    p('Cash and risk were reconstructed from actual fills, reservations and marked holdings; daily NAV reconciled to less than KRW 0.00001. The 009150 and 000810 headroom never recovered enough for even one share before 15:10. The two April 24 candidates shared the same cash, which later reached only KRW 0.624m. That could fund at most a very small addition before price, capacity and other checks, and cannot be treated as two independently funded opportunities. The journal lacks explicit first-rejection reason events, so this proves resource infeasibility in the observed state rather than the exact internal branch that returned first.')
    p('<strong>Preferred next frequency hypothesis:</strong> investigate the narrow stale-sector-flow exception already identified in the prior diagnosis. Keep stock flow, current price/sector confirmation, liquidity, score-band and original six-bar entry requirements. Re-evaluate every downstream gate for candidates whose sole recorded afternoon rejection was lagged sector flow; use no symbol exceptions. Place newly rescued candidates behind incumbents and use genuine residual cash/risk only. This is more selective than simply waiting longer or lowering every flow threshold.')
    p(f'There are {findings["flow_rescue_upper_bound"]["names"]} such OOS stage-local rejections on {findings["flow_rescue_upper_bound"]["days"]} days, but only <strong>{findings["flow_rescue_upper_bound"]["empty_days"]} currently empty days</strong> have even one such candidate. These are upper bounds, not four guaranteed new entry days. Other downstream gates and causal current-sector confirmation can still reject them. It cannot repair the sixteen daily-empty snapshots. Instrument the complete candidate → qualified → risk-approved → submitted → filled funnel and measure incremental net P&L, actual notional, displaced trades and entry days, not order count or token fills.')
    p('A separate fallback is an explicitly tested allocation change that spreads the fixed cohort risk allowance across simultaneous qualified candidates before adding rank-based concentration. It must compete on net return and common-shock risk, not just count. The July 3 fourth financial name would add same-sector activity, not necessarily diversification. Reserving risk for an unconfirmed higher-ranked candidate also has an opportunity cost. Do not assume either approach can preserve every incumbent allocation when the budget is already exhausted.')
    h('6. The experiment design needs better component qualification')
    p('The previous workflow allowed only full nominal qualifiers to receive combined stress tests. That is a reasonable promotion filter, but it left the promising selective-exit component’s robustness unknown because it did not create a new trade. A risk-only component should not need to solve the frequency objective before its execution sensitivity is measured. <strong>Separate component evidence from final policy promotion.</strong> Keep every final adoption gate unchanged, but pre-register stress and compounding comparisons for mechanism-active, IS-preserving components even if they miss a different objective.')
    rows=[]
    for title,key in [('Retained control, nominal','windows'),('Retained control, combined stress','stress'),('Retained control, capped sizing','capped')]:
        rows.append([title]+[num(control[key][w][k]) if k!='trades' else control[key][w][k] for w in ('train','oos') for k in ('return_pct','drawdown_pct','trades')])
    blocks.append(table(['Control mode','IS return %','IS DD %','IS entries','OOS return %','OOS DD %','OOS entries'],rows))
    p('Combined stress halves participation from 1% to 0.5% and raises slippage from 5 to 15 bps under the inherited cost assumptions. No new variant received that test; none should be called stress-qualified. Capped sizing improved control OOS return and DD, but cut IS return by 6.973 points, so a blanket compounding cap fails the stated objective. It remains a useful matched diagnostic. Every candidate/scenario/capped comparison must restore its own actual IS terminal history.')
    p('<strong>Recommended bounded order:</strong> (1) run the existing selective exit under stress/capped sizing and audit complete decision reasons; (2) test size-consistency and peer/liquidity separation as two explicit estimator ablations; (3) test one aligned-date, current-mark common-shock overlay; (4) test the single conditional opportunity-rescue mechanism after all-stage feasibility is established. Register at most one combination using components selected for their declared roles before seeing the combination result. Stop a component when its observed economic effect contradicts its hypothesis; do not open a threshold grid until one happens to pass.')
    p('For each component, disclose IS/OOS return and intraday DD, genuine entries and entry days, total/median incremental notional, winner and top-winner retention including removed trades, slow-loss versus first-open effects, component activation, allocation displacement, monthly concentration, stress and capped results. Event-exclusion arithmetic is descriptive; use native replays for causal portfolio comparisons. Use chronological development and untouched future source-qualified periods for independent confirmation. Repeated selection on the same backtest increases selection bias; see <a href="https://www.davidhbailey.com/dhbpapers/backtest-prob.pdf">Bailey et al., The Probability of Backtest Overfitting</a>.')
    h('7. History continuity is working; coverage and feature semantics still matter')
    p('IS starts August 7 because of the inherited sixty-session training plus one-session embargo schedule, not because earlier intraday history was thrown away. The OOS archive contains 217 prior sessions. Actual March 31 terminal history was restored before April 1 for each matching candidate, execution scenario and compounding mode. Tail-enabled runs restored their actual terminal liquidation panel and matched the independently constructed OOS prefix exactly. This diagnosis provides no evidence that an OOS cold start caused the drawdown.')
    p('The performance accounts restart flat at KRW 100m for comparable standalone IS/OOS measurements. That is separate from continuous market warm-up; it is not a single account carrying its March ending equity and positions into April. A full concatenated capital-path run would be a separate supplementary check and would not replace the matched-window gates.')
    p('The sparse auction-history issue remains: 96/186 IS and 21/46 OOS control trades have sparse auction support, including only one prior observation for the first OOS entry. History continuity cannot create missing auction observations. Dense price history does not cure this separate capacity input. The 103-name universe and taxonomy are fixed, not a point-in-time membership archive. Five-minute opening prices and lagged volumes remain execution proxies, with no order-book replay or guaranteed stop fill.')
    p('The legacy current-afternoon sector relative-volume feature was previously found to resolve to 1.0. Correcting its construction while retaining unchanged raw score bands altered IS ranking and hurt results. That is an unresolved feature-definition/calibration issue, not proof the legacy feature is economically valid. Handle it as a separately versioned, chronological feature-and-score migration after this bounded risk/frequency work; do not quietly change it, the taxonomy and the entry filters in the same experiment.')
    h('Decision and reproducibility')
    p('<strong>The best-supported next direction is selective exits plus correctly measured, quantity-consistent portfolio risk and a quality-preserving new-opportunity source.</strong> A blanket tighter stop, lower concentration cap, later confirmation window or global compounding cap has already shown material shortcomings. The next work should target those specific failure mechanisms. The retained control remains the comparison anchor; neither the existing selective exit nor these proposed repairs have yet earned promotion under all requirements.')
    p('This report authenticates original v3 completion artifacts, native audit passes and the selected-profile/result binding; reproduces six frozen tail quotes exactly; and reconciles the control cash ledger and daily NAV. It generates no new native policy performance. Full source hashes are in diagnosis.json. Prior verified strategy reports remain unchanged.')
    artifacts=[('Diagnostic evidence','diagnosis.json'),('Additional attribution','additional_findings.json'),('Chart','diagnosis.png'),('Prior verified report','../olr_precision_20261011/report.html'),('Retained selected research profile','../olr_precision_20261011/selected_research_policy.json')]
    p(' · '.join(f'<a href="{escape(url)}">{escape(name)}</a>' for name,url in artifacts))
