    (OUT/'report.html').write_text(html,encoding='utf-8')
    class Plain(HTMLParser):
        def __init__(self):super().__init__();self.parts=[];self.skip=False
        def handle_starttag(self,tag,attrs):
            if tag in ('style','script'):self.skip=True
            if tag in ('h1','h2','p','tr','figure'):self.parts.append('\n\n')
        def handle_endtag(self,tag):
            if tag in ('style','script'):self.skip=False
            if tag in ('td','th'):self.parts.append(' | ')
        def handle_data(self,t):
            if not self.skip:self.parts.append(t)
    parser=Plain();parser.feed(html)
    (OUT/'report.txt').write_text(''.join(parser.parts).strip()+'\n',encoding='utf-8')
